def is_valid_bst(root):
    def valid(n, lo, hi):
        if not n:
            return True
        if not (lo < n.val < hi):
            return False
        return valid(n.left, lo, n.val) and valid(n.right, n.val, hi)
    return valid(root, float('-inf'), float('inf'))
```

